import React, { useState } from 'react';
import { 
  Trash2, Map, Calendar, Star, LineChart, Users, 
  HardHat, FileText, Activity, ShieldAlert, ChevronLeft, AlertCircle,
  Settings, Zap
} from 'lucide-react';

const Dashboard = () => {
  const [currentView, setCurrentView] = useState('MENU');

  const allTabs = [
    { id: 'BINS', label: '01_BIN_MONITORING', icon: <Trash2 size={24}/> },
    { id: 'ZONES', label: '02_AREAS_&_ZONES', icon: <Map size={24}/> },
    { id: 'SCHEDULE', label: '03_COLL_SCHEDULE', icon: <Calendar size={24}/> },
    { id: 'POINTS', label: '04_REWARDS_POINTS', icon: <Star size={24}/> },
    { id: 'ANALYTICS', label: '05_SYS_ANALYTICS', icon: <LineChart size={24}/> },
    { id: 'CITIZENS', label: '06_CITIZEN_INFO', icon: <Users size={24}/> },
    { id: 'WORKERS', label: '07_WORKER_NODES', icon: <HardHat size={24}/> },
    { id: 'REPORTS', label: '08_SYS_REPORTS', icon: <FileText size={24}/> },
  ];

  // --- 1. THE MAIN MENU (Compact Switchboard) ---
  const MainMenu = () => (
    <div className="w-full bg-[#A1AED1] border-[6px] border-[#47510B] rounded-[35px] p-8 shadow-[12px_12px_0_0_#47510B] animate-slot relative overflow-hidden">
      {/* Decorative "Circuit" Lines */}
      <div className="absolute top-0 right-0 w-32 h-32 bg-[#CAD23C] opacity-10 rounded-full -mr-16 -mt-16 blur-3xl" />

      <div className="flex items-center justify-between mb-8 border-b-4 border-[#47510B]/10 pb-4">
        <div className="flex items-center gap-2">
            <Zap size={16} className="text-[#AB1717]" />
            <p className="text-[10px] font-black uppercase tracking-[0.4em] text-[#47510B]">System_Matrix_Active</p>
        </div>
        <p className="text-[10px] font-black uppercase text-[#AB1717] opacity-60">Nodes_Detected: 08</p>
      </div>

      {/* GRID: Reduced padding and gap for a tighter, high-tech look */}
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-5">
        {allTabs.map((tab) => (
          <button
            key={tab.id}
            onClick={() => setCurrentView(tab.id)}
            className="group relative flex flex-col items-center justify-center gap-3 p-6 rounded-[24px] border-[5px] border-[#47510B] bg-[#FDFAD8] transition-all duration-200 hover:-translate-y-1 hover:bg-[#CAD23C] active:translate-y-1 shadow-[0_8px_0_0_#47510B] active:shadow-none"
          >
            {/* Shrunken Icon Container */}
            <div className="text-[#AB1717] group-hover:text-[#47510B] transition-transform group-hover:scale-110">
              {tab.icon}
            </div>

            <span className="text-[9px] md:text-[10px] font-black uppercase tracking-tight text-[#47510B] text-center leading-tight">
              {tab.label.split('_').slice(1).join(' ')}
            </span>

            {/* Corner Accent */}
            <div className="absolute top-2 right-2 w-1.5 h-1.5 rounded-full bg-[#47510B] group-hover:bg-[#AB1717]" />
          </button>
        ))}
      </div>
    </div>
  );

  // --- 2. THE DETAIL VIEW ---
  const DetailView = ({ id }) => (
    <div className="w-full animate-slot flex flex-col gap-6">
      <button 
        onClick={() => setCurrentView('MENU')}
        className="flex items-center gap-2 bg-[#47510B] text-[#FDFAD8] px-5 py-2.5 rounded-xl font-black uppercase text-[10px] w-fit hover:bg-[#AB1717] transition-all shadow-[4px_4px_0_0_#CAD23C] hover:translate-x-1"
      >
        <ChevronLeft size={16} /> Return.to.Base
      </button>

      <div className="bg-white border-[6px] border-[#47510B] rounded-[40px] p-10 md:p-16 text-center flex flex-col items-center justify-center shadow-[15px_15px_0_0_#A1AED1] min-h-[450px] relative overflow-hidden">
        {/* Subtle Grid Background */}
        <div className="absolute inset-0 opacity-[0.03] pointer-events-none bg-[px] bg-[radial-gradient(#47510B_1px,transparent_0)] [background-size:20px_20px]" />

        <AlertCircle size={64} className="text-[#AB1717] mb-4 animate-pulse" />
        <h2 className="text-4xl md:text-5xl font-black italic text-[#47510B] uppercase tracking-tighter mb-2">
          {id} <span className="text-[#AB1717]">_LINK</span>
        </h2>
        <div className="w-16 h-1.5 bg-[#CAD23C] rounded-full mb-6" />
        <p className="text-[10px] font-bold text-[#47510B] opacity-40 uppercase tracking-[0.6em]">
          Protocol_V3 // Secure_Stream
        </p>
      </div>
    </div>
  );

  return (
    <div className="w-full min-h-screen bg-[#FDFAD8] p-6 md:p-10 flex items-center justify-center font-sans">

      <div className="w-full max-w-[1100px] flex flex-col gap-6">

        {/* HEADER: Sleeker Profile */}
        <div className="bg-[#AB1717] border-[6px] border-[#47510B] rounded-t-[45px] rounded-b-[15px] p-6 md:px-10 md:py-8 shadow-[8px_8px_0_0_#47510B] relative">
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-5">
              <div className="bg-[#FDFAD8] p-2.5 rounded-xl border-4 border-[#47510B] shadow-[4px_4px_0_0_#47510B]">
                <ShieldAlert size={28} className="text-[#AB1717]" strokeWidth={2.5} />
              </div>
              <div>
                <p className="text-[9px] font-black uppercase tracking-[0.5em] text-[#FDFAD8] opacity-50 mb-1">Central.Processing</p>
                <h1 className="text-2xl md:text-4xl font-black italic text-[#FDFAD8] uppercase tracking-tighter leading-none">
                  TRASH<span className="text-[#CAD23C]">2</span>TRACK
                </h1>
              </div>
            </div>

            <div className="flex items-center gap-4">
               <div className="hidden md:flex flex-col items-end mr-4">
                  <span className="text-[8px] font-black text-[#CAD23C] uppercase mb-1">Internal_Temp: 32°C</span>
                  <div className="w-16 h-1 bg-[#47510B] rounded-full overflow-hidden">
                    <div className="w-2/3 h-full bg-[#CAD23C]" />
                  </div>
               </div>
               <Activity className="text-[#CAD23C] animate-pulse" size={28} />
            </div>
          </div>
        </div>

        {/* LOGIC AREA */}
        <div className="transition-all duration-300">
           {currentView === 'MENU' ? <MainMenu /> : <DetailView id={currentView} />}
        </div>

        {/* FOOTER */}
        <div className="flex justify-between items-center px-4 opacity-40">
            <Settings size={14} className="text-[#47510B] animate-spin-slow" />
            <p className="text-[8px] font-black uppercase tracking-[0.8em] text-[#47510B]">
              Terminal_ID: 0x882_T2T
            </p>
            <div className="flex gap-1">
               <div className="w-1.5 h-1.5 rounded-full bg-[#47510B]" />
               <div className="w-1.5 h-1.5 rounded-full bg-[#AB1717]" />
            </div>
        </div>
      </div>
    </div>
  );
};

